#!/usr/bin/env bash
# R-CBG agent verification — does the agent's measured handshake RTT agree
# with an independently known RTT to the same host?
#
# Generates traffic from THIS box to the node's honeypot ports, then reads back
# what the agent recorded and compares against ping.
#
# Two things this is careful about:
#   * ping runs CONCURRENTLY with the connections, so both sample the same few
#     seconds of the path rather than being minutes apart.
#   * only records generated by this run are considered. The log accumulates,
#     and comparing an accumulated minimum against a fresh ping conflates path
#     drift with measurement error.
#
# Usage: deploy/verify-node.sh <alias> [connections]

set -euo pipefail
REPO="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
ALIAS="${1:-}"
N="${2:-12}"
[ -z "$ALIAS" ] && { echo "usage: $0 <alias> [connections]" >&2; exit 2; }

HOSTNAME_=$(ssh -G "$ALIAS" | awk '/^hostname /{print $2}')
IP=$(getent ahostsv4 "$HOSTNAME_" | awk 'NR==1{print $1}')
[ -z "$IP" ] && { echo "cannot resolve $HOSTNAME_" >&2; exit 1; }

PORTS=$(ssh -o BatchMode=yes "$ALIAS" \
  "awk -F'[][]' '/^listen_ports/{print \$2}' /etc/rcbg/agent.toml" | tr -d ' ')
echo "node=$ALIAS ip=$IP ports=[$PORTS]"

# Ask the node what source address it sees us as; with NAT this is not our own.
MYIP=$(ssh -o BatchMode=yes "$ALIAS" 'echo $SSH_CONNECTION' 2>/dev/null | awk '{print $1}')
echo "    (this box reaches $ALIAS as ${MYIP:-unknown})"

TMP=$(mktemp -d); trap 'rm -rf "$TMP"' EXIT

# Mark the start a little early: clocks between the two boxes are not identical,
# and the record timestamp is taken on the node.
SINCE=$(date -u -d '60 seconds ago' +%Y-%m-%dT%H:%M:%SZ 2>/dev/null \
        || date -u -v-60S +%Y-%m-%dT%H:%M:%SZ)

echo "==> measuring ping and generating $N connections per port (concurrently)"
ping -c "$((N * 3))" -i 0.25 -W 2 -q "$IP" > "$TMP/ping.out" 2>&1 &
PING_PID=$!

for p in ${PORTS//,/ }; do
  for _ in $(seq 1 "$N"); do
    timeout 3 bash -c "exec 3<>/dev/tcp/$IP/$p" 2>/dev/null || true
  done
done
wait "$PING_PID" || true

PING_MIN=$(awk -F'= ' '/rtt|round-trip/{split($2,a,"/"); print a[1]}' "$TMP/ping.out")
if [ -z "$PING_MIN" ]; then
  echo "ping produced no result; cannot establish ground truth" >&2
  cat "$TMP/ping.out" >&2
  exit 1
fi
echo "    ping min = ${PING_MIN} ms (concurrent with the connections)"

echo "==> waiting for flush"
sleep 14

echo "==> what the agent recorded"
ssh -o BatchMode=yes "$ALIAS" "cat /var/lib/rcbg/measurements.jsonl" 2>/dev/null \
  | python3 "$REPO/deploy/analyze-verify.py" "$PING_MIN" "$MYIP" "$SINCE"
